import{_ as a,o as r,c as e,ai as o}from"./chunks/framework.ampVZV4B.js";const k=JSON.parse('{"title":"Python 框架总结","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/python/frameworks.md","filePath":"tech-system/backend/python/frameworks.md"}'),n={name:"tech-system/backend/python/frameworks.md"};function s(l,t,d,i,h,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="python-框架总结" tabindex="-1">Python 框架总结 <a class="header-anchor" href="#python-框架总结" aria-label="Permalink to “Python 框架总结”">​</a></h1><blockquote><p>语言快，不代表框架随便选。这里只谈 <strong>我会用哪个、为什么。</strong></p></blockquote><hr><h2 id="fastapi" tabindex="-1">FastAPI <a class="header-anchor" href="#fastapi" aria-label="Permalink to “FastAPI”">​</a></h2><ul><li><strong>我最常用</strong>：写 AI/工具类 HTTP 服务</li><li>类型注解 → 自动校验与文档，和「对外契约」很搭</li><li>async 适合等模型、等下游</li></ul><p><strong>适合：</strong> 内部 API、模型代理、给 Java 调用的胶水层。</p><hr><h2 id="flask" tabindex="-1">Flask <a class="header-anchor" href="#flask" aria-label="Permalink to “Flask”">​</a></h2><ul><li>轻、灵活、历史包袱项目多</li><li>适合非常小的脚本服务或遗留维护</li></ul><p><strong>判断：</strong> 新项目我更愿意直接 FastAPI；维护老 Flask 再学够用即可。</p><hr><h2 id="django" tabindex="-1">Django <a class="header-anchor" href="#django" aria-label="Permalink to “Django”">​</a></h2><ul><li>「电池全」：Admin、ORM、用户体系齐全</li><li>适合要快速出带后台的完整站点</li></ul><p><strong>判断：</strong> 我的主业务已在 Java；Django 不是默认选项。只有「独立小站 + 强 Admin」才考虑。</p><hr><h2 id="我的选择" tabindex="-1">我的选择 <a class="header-anchor" href="#我的选择" aria-label="Permalink to “我的选择”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>选择</th></tr></thead><tbody><tr><td>AI / 自动化 API</td><td><strong>FastAPI</strong></td></tr><tr><td>几行脚本 + 临时 HTTP</td><td>Flask 或甚至不写框架</td></tr><tr><td>完整 Python 业务站</td><td>Django（少见）</td></tr><tr><td>任务队列</td><td>先 Redis 列表/简单 worker；复杂再上 Celery</td></tr></tbody></table><p><strong>原则：</strong> Python 框架服务于「快」和「旁路」；核心交易与权限仍放 Java。</p>',18)])])}const m=a(n,[["render",s]]);export{k as __pageData,m as default};
